    # Bachelor should receive 2 points, and non-degree should receive 1 point.
    if applicant.parent_education == 'PhD':
        score += 4
    elif applicant.parent_education == 'Master':
        score += 3
    elif applicant.parent_education == 'Bachelor':
        score += 2
    elif applicant.parent_education == 'non-degree':
        score += 1

    # GPA: GT 3.5 should get 2 points, GT 3.0 should get 1 point.
    if applicant.GPA >= 3.5:
        score += 2
    elif applicant.GPA >= 3.0:
        score += 1

    # Relevant experience: More years should get more points, like 2 years experience should get 2 points, 1 year should get 1 point.
    if applicant.relevant_experience >= 2:
        score += 2
    elif applicant.relevant_experience >= 1:
        score += 1

    # Skills: More matching skills should get more points, say 3 matching should get 2 points, 
    # and 1 matching should get 1 point. 
    relevant_skills = ['welding', 'fabrication', 'mechanical design', 'machine operation']
    skill_matches = [skill for skill in applicant.skills if skill in relevant_skills]
    score += len(skill_matches)

    # Personal statement and recommendation letters: if they're high quality, should each get 2 points.
    if applicant.personal_statement == 'high quality':
        score += 2
    if applicant.recommendation_letters == 'high quality':
        score += 2

    return score
